import subprocess
from ipaddress import IPv4Network
def task_func(ip_range):
    results = {}
    for ip in IPv4Network(ip_range):
        try:
            subprocess.run(['ping', '-c', '1', '-W', '1', str(ip)], check=True, stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
            results[str(ip)] = True
        except subprocess.CalledProcessError:
            results[str(ip)] = False
    return results

