import time
def task_func(url):
    is_url_verified = len(url) > 0
    if platform.system() == 'Windows':
        process = subprocess.Popen(['start', url], shell=is_url_verified)
    elif platform.system() == 'Darwin':
        process = subprocess.Popen(['open', url], shell=is_url_verified)
    else:
        process = subprocess.Popen(['xdg-open', url], shell=is_url_verified)
