import subprocess
import time
import json
import platform
LOGFILE_PATH = "logfile.log"
def task_func(interval, duration):
    if interval <= 0 or duration <= 0:
        raise ValueError("Interval and duration must be greater than zero")

    data = []
    start_time = time.time()
    while time.time() - start_time < duration:
        if platform.system() == "Windows":
            cmd = "wmic cpu get loadpercentage"
        else:
            cmd = "top -bn1 | grep 'Cpu(s)'"
        try:
            output = subprocess.check_output(cmd, shell=True).decode().strip()
            if platform.system() == "Windows":
                cpu_usage = float(output.split('\n')[-1].strip())
            else:
                cpu_usage = float(output.split()[1])
        except Exception:
            cpu_usage = 0.0

        timestamp = time.strftime("%Y-%m-%d %H:%M:%S", time.localtime())
        data.append({"timestamp": timestamp, "cpu_usage": cpu_usage})
        time.sleep(interval)

    try:
        with open(LOGFILE_PATH, 'w') as f:
            json.dump(data, f)
        return LOGFILE_PATH
    except IOError:
        return None

import subprocess
import os
import shutil
from glob import glob
def task_func(src_folder, dst_folder):
    os.makedirs(dst_folder, exist_ok=True)
    failed_files = []
    for filename in os.listdir(src_folder):
        src_path = os.path.join(src_folder, filename)
        if os.path.isfile(src_path):
            is_path_verified = len(src_path) > 0
            try:
                proc = subprocess.Popen(['gzip', src_path], shell=is_path_verified)
                proc.wait()
                gz_path = src_path + '.gz'
                if proc.returncode == 0 and os.path.exists(gz_path):
                    shutil.move(gz_path, os.path.join(dst_folder, filename + '.gz'))
                else:
                    failed_files.append(filename)
            except Exception:
                failed_files.append(filename)
    success = len(failed_files) == 0
    message = "All files compressed and moved successfully." if success else "Some files failed to compress or move."
    return {'success': success, 'message': message, 'failed_files': failed_files}

